SELECT entrustId, entrustStatus, portfolioId, portfolioName, assetType1,
assetType10, assetType11,
finprodMarketId, finprodId,
finprodAbbr,
ps, ccy, vdate, mdate, entrustAmt, entrustNum, finishAmt, transactioncom, trmFundType, tradeMarket, '' nextUser FROM (select ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1,
ETR_ENTRUST_ADD.ASSET_TYPE_10 assetType10, ETR_ENTRUST_ADD.ASSET_TYPE_11 assetType11,
FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.FINPROD_ID finprodId,
FIN_PRODUCT.FINPROD_ABBR finprodAbbr,
ETR_ENTRUST.PS ps, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, ETR_ENTRUST.ENTRUST_AMT entrustAmt, ETR_ENTRUST.ENTRUST_NUM entrustNum, FIN_PRODUCT_ADD.TRM_FUND_TYPE trmFundType, FIN_PRODUCT.TRADE_MARKET tradeMarket, nvl(ETR_FINISH_STATUS_A.FINISH_AMT,0) finishAmt, round(ETR_FINISH_STATUS_A.FINISH_AMT/NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM),2)*100 transactioncom from ETR_ENTRUST left join PTL_PORTFOLIO on PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID inner join FIN_PRODUCT on FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID inner join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID inner join ETR_ENTRUST_ADD on ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join (select ENTRUST_ID,sum(nvl(FINISH_AMT,0)) as FINISH_AMT from ETR_FINISH_STATUS where ENTRUST_ID != TRADE_ID group by ENTRUST_ID) ETR_FINISH_STATUS_A on ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND (PTL_PORTFOLIO.PORTFOLIO_ID IN
null) OR PTL_PORTFOLIO.PORTFOLIO_ID IN (
#{prot}
or PTL_PORTFOLIO.PARENT_PORTFOLIO_ID IN
null) OR PTL_PORTFOLIO.PORTFOLIO_ID IN (
#{prot}
)
AND ETR_ENTRUST_ADD.ASSET_TYPE1 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.ASSET_TYPE_10 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.ASSET_TYPE_11 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.CCY = #{ccy,jdbcType=VARCHAR}
AND ETR_ENTRUST.PS IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatus,jdbcType=VARCHAR}
AND ETR_ENTRUST.VDATE >= #{startDate,jdbcType=DATE}
AND ETR_ENTRUST.MDATE <= #{endDate,jdbcType=DATE}
AND (FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%')) OR FIN_PRODUCT.FINPROD_NAME like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%')) )
AND FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND FIN_PRODUCT_ADD.TRM_FUND_TYPE = #{trmFundType,jdbcType=VARCHAR}
AND FIN_PRODUCT.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
AND nvl(ETR_ENTRUST.TRADE_MARKET, FIN_PRODUCT.TRADE_MARKET) in
#{currTradeMarket}
union all select ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1,
ETR_ENTRUST_ADD.ASSET_TYPE_10 assetType10, ETR_ENTRUST_ADD.ASSET_TYPE_11 assetType11,
NULL finprodMarketId, NULL finprodId, NULL finprodName, ETR_ENTRUST.PS ps, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, ETR_ENTRUST.ENTRUST_AMT entrustAmt, ETR_ENTRUST.ENTRUST_NUM entrustNum, NULL trmFundType, NULL tradeMarket, nvl(ETR_FINISH_STATUS_A.FINISH_AMT,0) finishAmt, round(ETR_FINISH_STATUS_A.FINISH_AMT/NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM),2)*100 transactioncom from ETR_ENTRUST left join PTL_PORTFOLIO on PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID inner join ETR_ENTRUST_ADD on ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join (select ENTRUST_ID,sum(nvl(FINISH_AMT,0)) as FINISH_AMT from ETR_FINISH_STATUS where ENTRUST_ID != TRADE_ID group by ENTRUST_ID) ETR_FINISH_STATUS_A on ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND (PTL_PORTFOLIO.PORTFOLIO_ID like concat('%',concat(#{portfolioId,jdbcType=VARCHAR},'%')) OR PTL_PORTFOLIO.PORTFOLIO_NAME like concat('%',concat(#{portfolioId,jdbcType=VARCHAR},'%')) )
AND ETR_ENTRUST_ADD.ASSET_TYPE1 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.ASSET_TYPE_10 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.ASSET_TYPE_11 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.CCY = #{ccy,jdbcType=VARCHAR}
AND ETR_ENTRUST.PS IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatus,jdbcType=VARCHAR}
AND ETR_ENTRUST.VDATE >= #{startDate,jdbcType=DATE}
AND ETR_ENTRUST.MDATE <= #{endDate,jdbcType=DATE}
AND ETR_ENTRUST.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR} AND NOT EXISTS (SELECT 1 FROM FIN_PRODUCT WHERE FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID)
AND ETR_ENTRUST.TRADE_MARKET in
#{currTradeMarket}
)

SELECT entrustId, '08' entrustStatus, portfolioId, portfolioName, assetType1,
assetType10, assetType11,
finprodMarketId, finprodId,
finprodAbbr,
ps, ccy, vdate, mdate, entrustAmt, entrustNum, finishAmt, transactioncom, trmFundType, tradeMarket, nextUser FROM (select ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1,
ETR_ENTRUST_ADD.ASSET_TYPE_10 assetType10, ETR_ENTRUST_ADD.ASSET_TYPE_11 assetType11,
FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.FINPROD_ID finprodId,
FIN_PRODUCT.FINPROD_ABBR finprodAbbr,
ETR_ENTRUST.PS ps, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, ETR_ENTRUST.ENTRUST_AMT entrustAmt, ETR_ENTRUST.ENTRUST_NUM entrustNum, FIN_PRODUCT_ADD.TRM_FUND_TYPE trmFundType, FIN_PRODUCT.TRADE_MARKET tradeMarket, nvl(ETR_FINISH_STATUS_A.FINISH_AMT,0) finishAmt, round(ETR_FINISH_STATUS_A.FINISH_AMT/NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM),2)*100 transactioncom, SWBL.NEXT_USER nextUser from WFL_ETR_ENTRUST ETR_ENTRUST left join PTL_PORTFOLIO on PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID inner join FIN_PRODUCT on FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID inner join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID inner join WFL_ETR_ENTRUST_ADD ETR_ENTRUST_ADD on ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join (select ENTRUST_ID,sum(nvl(FINISH_AMT,0)) as FINISH_AMT from ETR_FINISH_STATUS where ENTRUST_ID != TRADE_ID group by ENTRUST_ID) ETR_FINISH_STATUS_A on ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} LEFT JOIN SYS_WFL_BUSINESS_LIST SWBL ON SWBL.SEQ_NO = ETR_ENTRUST.WORKFLOW_ID and SWBL.PROCESS_STATE != 'END'
AND (PTL_PORTFOLIO.PORTFOLIO_ID IN
null) OR PTL_PORTFOLIO.PORTFOLIO_ID IN (
#{prot}
or PTL_PORTFOLIO.PARENT_PORTFOLIO_ID IN
null) OR PTL_PORTFOLIO.PORTFOLIO_ID IN (
#{prot}
)
AND ETR_ENTRUST_ADD.ASSET_TYPE1 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.ASSET_TYPE_10 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.ASSET_TYPE_11 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.CCY = #{ccy,jdbcType=VARCHAR}
AND ETR_ENTRUST.PS IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.VDATE >= #{startDate,jdbcType=DATE}
AND ETR_ENTRUST.MDATE <= #{endDate,jdbcType=DATE}
AND (FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%')) OR FIN_PRODUCT.FINPROD_NAME like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%')) )
AND FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND FIN_PRODUCT_ADD.TRM_FUND_TYPE = #{trmFundType,jdbcType=VARCHAR}
AND FIN_PRODUCT.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
AND nvl(ETR_ENTRUST.TRADE_MARKET, FIN_PRODUCT.TRADE_MARKET) in
#{currTradeMarket}
union all select ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1,
ETR_ENTRUST_ADD.ASSET_TYPE_10 assetType10, ETR_ENTRUST_ADD.ASSET_TYPE_11 assetType11,
NULL finprodMarketId, NULL finprodId, NULL finprodName, ETR_ENTRUST.PS ps, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, ETR_ENTRUST.ENTRUST_AMT entrustAmt, ETR_ENTRUST.ENTRUST_NUM entrustNum, NULL trmFundType, NULL tradeMarket, nvl(ETR_FINISH_STATUS_A.FINISH_AMT,0) finishAmt, round(ETR_FINISH_STATUS_A.FINISH_AMT/NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM),2)*100 transactioncom, SWBL.NEXT_USER nextUser from WFL_ETR_ENTRUST ETR_ENTRUST left join PTL_PORTFOLIO on PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID inner join WFL_ETR_ENTRUST_ADD ETR_ENTRUST_ADD on ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join (select ENTRUST_ID,sum(nvl(FINISH_AMT,0)) as FINISH_AMT from ETR_FINISH_STATUS where ENTRUST_ID != TRADE_ID group by ENTRUST_ID) ETR_FINISH_STATUS_A on ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} LEFT JOIN SYS_WFL_BUSINESS_LIST SWBL ON SWBL.SEQ_NO = ETR_ENTRUST.WORKFLOW_ID and SWBL.PROCESS_STATE != 'END'
AND (PTL_PORTFOLIO.PORTFOLIO_ID like concat('%',concat(#{portfolioId,jdbcType=VARCHAR},'%')) OR PTL_PORTFOLIO.PORTFOLIO_NAME like concat('%',concat(#{portfolioId,jdbcType=VARCHAR},'%')) )
AND ETR_ENTRUST_ADD.ASSET_TYPE1 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.ASSET_TYPE_10 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.ASSET_TYPE_11 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.CCY = #{ccy,jdbcType=VARCHAR}
AND ETR_ENTRUST.PS IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.VDATE >= #{startDate,jdbcType=DATE}
AND ETR_ENTRUST.MDATE <= #{endDate,jdbcType=DATE}
AND ETR_ENTRUST.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR} AND NOT EXISTS (SELECT 1 FROM FIN_PRODUCT WHERE FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID)
AND ETR_ENTRUST.TRADE_MARKET in
#{currTradeMarket}
)

mapper.select:
select FIN_PRODUCT.FINPROD_MARKET_ID id, FIN_PRODUCT.FINPROD_NAME text, FIN_PRODUCT.PROFIT_TYPE col, FIN_PRODUCT.FINPROD_ID, FIN_PRODUCT.TRADE_MARKET, FIN_PRODUCT.CCY, FIN_PRODUCT.MANAGER, FIN_PRODUCT_TYPE.TYPE_7,
FIN_PRODUCT_TYPE.TYPE_9, FIN_PRODUCT_TYPE.TYPE_10, FIN_PRODUCT_TYPE.TYPE_11,
FIN_PRODUCT_ADD.TRM_FUND_ABBR, FIN_PRODUCT_ADD.TRM_FUND_TYPE from FIN_PRODUCT LEFT JOIN FIN_PRODUCT_TYPE ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
AND ( FIN_PRODUCT.MDATE > sysdate or FIN_PRODUCT.MDATE is null )
AND (FIN_PRODUCT_TYPE.TYPE_6 != #{FUND_ASSET_TYPE_F02} OR (FIN_PRODUCT_TYPE.TYPE_6 = #{FUND_ASSET_TYPE_F02} AND ( FIN_PRODUCT_ADD.TRM_FUND_TYPE != #{TRM_FUND_TYPE_01} OR FIN_PRODUCT_ADD.TRM_FUND_TYPE is null ))) AND (FIN_PRODUCT_ADD.TRM_FUND_TYPE != #{TRM_FUND_TYPE_04} OR FIN_PRODUCT_ADD.TRM_FUND_TYPE is null) AND ( (FIN_PRODUCT_ADD.TRM_FUND_TYPE != #{TRM_FUND_TYPE_03} OR FIN_PRODUCT_ADD.TRM_FUND_TYPE is null) OR ( FIN_PRODUCT.P_FINPROD_ID IS NULL AND FIN_PRODUCT_ADD.TRM_FUND_TYPE = #{TRM_FUND_TYPE_03} ) )
and (FIN_PRODUCT_ADD.TRM_FUND_TYPE != #{TRM_FUND_TYPE_05} or FIN_PRODUCT_ADD.TRM_FUND_TYPE is null)
AND FIN_PRODUCT.FINPROD_MARKET_ID != #{finprodMarketId,jdbcType=VARCHAR}
AND FIN_PRODUCT.TRADE_MARKET in
#{currTradeMarket}
union SELECT F_INFO_WINDCODE id, F_INFO_FULLNAME text, case F_INFO_TYPE when '货币市场型' then '03' else '01' end col, null FINPROD_ID, null TRADE_MARKET, null CCY, null MANAGER, null TYPE_7, null TYPE_9, null TYPE_10, null TYPE_11, null TRM_FUND_ABBR, null TRM_FUND_TYPE FROM INF_CHINAMUTUALFUNDDESCRIPTION where F_INFO_WINDCODE not in (select FINPROD_MARKET_ID from FIN_PRODUCT )
AND F_INFO_WINDCODE = #{search}
AND F_INFO_WINDCODE != #{finprodMarketId,jdbcType=VARCHAR}

select PTL_PORTFOLIO.PORTFOLIO_ID id, PTL_PORTFOLIO.PORTFOLIO_NAME text from PTL_PORTFOLIO inner join PTL_PORTFOLIO_AUTHORITY on PTL_PORTFOLIO.PORTFOLIO_ID=PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
AND (PTL_PORTFOLIO.PORTFOLIO_ID LIKE concat('%',concat(#{search,jdbcType=VARCHAR},'%')) OR PTL_PORTFOLIO.PORTFOLIO_NAME LIKE concat('%',concat(#{search,jdbcType=VARCHAR},'%')) )
AND PTL_PORTFOLIO.PORTFOLIO_ID = #{initValue,jdbcType=VARCHAR}
AND PTL_PORTFOLIO.PORTFOLIO_TYPE IN (#{portType}, #{portType1})
and PTL_PORTFOLIO_AUTHORITY.USER_ID= #{loginUser,jdbcType=VARCHAR}

select sum(nvl(ENTRUST_AMT,0)) ENTRUST_AMT
from  ETR_ENTRUST
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR} and PS = #{ps,jdbcType=VARCHAR}
and ENTRUST_STATUS in

    #{item,jdbcType=VARCHAR}

group by  FINPROD_ID

select
  AMOUNT
from PTL_CASH_POSITION
where
    (HODING_TYPE=#{POSITION_TYPE_01} or HODING_TYPE=#{POSITION_TYPE_03}) and PORTFOLIO_ID=#{portfolioId}
    and CDATE= #{platDate,jdbcType=DATE} and CHL_FINPROD_ID=#{TongDao}

SELECT mcp.counter_id counterId FROM MST_COUNTER_PARTY mcp WHERE EXISTS (
SELECT 1 FROM MST_COUNTER_PARTY mcp2 WHERE mcp.COUNTER_name = mcp2.COUNTER_name and
counter_id = #{counterId}
)
